mapper.select:
SELECT COUNT(*)
FROM course_detail cd
WHERE cd.status = 1

    AND cd.id <> #{excludeCourseId}

  AND (
    TRIM(LEADING '/' FROM REPLACE(COALESCE(NULLIF(TRIM(cd.cover_path), ''), NULLIF(TRIM(cd.thumbnail_url), '')), CHAR(92), '/')) = #{relativePath}
    OR TRIM(LEADING '/' FROM REPLACE(COALESCE(NULLIF(TRIM(cd.original_file_path), ''), NULLIF(TRIM(cd.files), '')), CHAR(92), '/')) = #{relativePath}
    OR TRIM(LEADING '/' FROM REPLACE(NULLIF(TRIM(cd.preview_file_path), ''), CHAR(92), '/')) = #{relativePath}
  )

SELECT SUM(reference_count)
FROM (
    SELECT COUNT(*) AS reference_count FROM team_page_images
    WHERE TRIM(LEADING '/' FROM REPLACE(NULLIF(TRIM(imageUrl), ''), CHAR(92), '/')) = #{relativePath}
    UNION ALL
    SELECT COUNT(*) FROM banner
    WHERE TRIM(LEADING '/' FROM REPLACE(NULLIF(TRIM(imageUrl), ''), CHAR(92), '/')) = #{relativePath}
    UNION ALL
    SELECT COUNT(*) FROM news
    WHERE TRIM(LEADING '/' FROM REPLACE(NULLIF(TRIM(imageUrl), ''), CHAR(92), '/')) = #{relativePath}
    UNION ALL
    SELECT COUNT(*) FROM `user`
    WHERE TRIM(LEADING '/' FROM REPLACE(NULLIF(TRIM(imageUrl), ''), CHAR(92), '/')) = #{relativePath}
) public_references

SELECT COUNT(*)
FROM public_image_asset asset
WHERE TRIM(LEADING '/' FROM REPLACE(NULLIF(TRIM(asset.relative_path), ''), CHAR(92), '/')) = #{relativePath}

    AND asset.asset_id <> #{excludeAssetId}
